export const propertyName = (node) => {
  if (node?.type === "Identifier" || node?.type === "JSXIdentifier") {
    return node.name;
  }

  if (node?.type === "Literal") {
    return String(node.value);
  }

  return null;
};

export const importSourceValue = (node) => {
  const value = node?.source?.value;
  return String(value) === value ? value : "";
};

const declaredVariable = (sourceCode, node, name) =>
  sourceCode
    .getDeclaredVariables(node)
    .find((variable) => variable.name === name) ?? null;

export const createBindingTracker = (
  sourceCode,
  globalSemantics = new Map()
) => {
  const bindingSemantics = new Map();
  const referenceVariables = new Map();

  for (const scope of sourceCode.scopeManager.scopes) {
    for (const reference of scope.references) {
      referenceVariables.set(reference.identifier, reference.resolved ?? null);
    }
  }

  const semanticOfIdentifier = (node) => {
    if (node?.type !== "Identifier") {
      return null;
    }

    const variable = referenceVariables.get(node);
    if (variable) {
      return bindingSemantics.get(variable) ?? null;
    }

    return variable === null ? (globalSemantics.get(node.name) ?? null) : null;
  };

  const semanticOfExpression = (node) => {
    if (node?.type === "Identifier") {
      return semanticOfIdentifier(node);
    }

    if (node?.type === "MemberExpression") {
      const object = semanticOfExpression(node.object);
      const member =
        !node.computed || node.property?.type === "Literal"
          ? propertyName(node.property)
          : null;
      return object && member ? `${object}.${member}` : null;
    }

    if (
      node?.type === "ChainExpression" ||
      node?.type === "TSAsExpression" ||
      node?.type === "TSInstantiationExpression" ||
      node?.type === "TSNonNullExpression" ||
      node?.type === "TSTypeAssertion"
    ) {
      return semanticOfExpression(node.expression);
    }

    return null;
  };

  const semanticOfTypeName = (node) => {
    if (node?.type === "Identifier") {
      return semanticOfIdentifier(node);
    }

    if (node?.type === "TSQualifiedName") {
      const left = semanticOfTypeName(node.left);
      const right = propertyName(node.right);
      return left && right ? `${left}.${right}` : null;
    }

    return null;
  };

  const setDeclaredSemantic = (node, name, semantic) => {
    const variable = declaredVariable(sourceCode, node, name);
    if (variable && semantic) {
      bindingSemantics.set(variable, semantic);
    }
  };

  const setReferencedSemantic = (node, semantic) => {
    const variable = referenceVariables.get(node);
    if (variable && semantic) {
      bindingSemantics.set(variable, semantic);
    }
  };

  const trackPattern = (pattern, sourceSemantic, declarationNode = null) => {
    if (!sourceSemantic) {
      return;
    }

    if (pattern?.type === "Identifier") {
      if (declarationNode) {
        setDeclaredSemantic(declarationNode, pattern.name, sourceSemantic);
      } else {
        setReferencedSemantic(pattern, sourceSemantic);
      }
      return;
    }

    if (pattern?.type !== "ObjectPattern") {
      return;
    }

    for (const property of pattern.properties ?? []) {
      if (property.type !== "Property") {
        continue;
      }

      const member = propertyName(property.key);
      if (!member) {
        continue;
      }

      const target =
        property.value?.type === "AssignmentPattern"
          ? property.value.left
          : property.value;
      trackPattern(target, `${sourceSemantic}.${member}`, declarationNode);
    }
  };

  const clearPattern = (pattern) => {
    if (pattern?.type === "Identifier") {
      const variable = referenceVariables.get(pattern);
      if (variable) {
        bindingSemantics.delete(variable);
      }
      return;
    }

    if (pattern?.type === "ObjectPattern") {
      for (const property of pattern.properties ?? []) {
        if (property.type === "Property") {
          clearPattern(
            property.value?.type === "AssignmentPattern"
              ? property.value.left
              : property.value
          );
        }
      }
    }
  };

  return {
    calledSemantic: (node) =>
      node?.type === "CallExpression"
        ? semanticOfExpression(node.callee)
        : null,
    semanticOfExpression,
    semanticOfTypeName,
    trackAssignment(node) {
      if (node.operator === "=") {
        const semantic = semanticOfExpression(node.right);
        if (semantic) {
          trackPattern(node.left, semantic);
        } else {
          clearPattern(node.left);
        }
      }
    },
    trackImport(node, importSemantic) {
      const source = importSourceValue(node);
      for (const specifier of node.specifiers ?? []) {
        const imported =
          specifier.type === "ImportSpecifier"
            ? propertyName(specifier.imported)
            : null;
        const semantic = importSemantic(source, specifier.type, imported);
        if (semantic && specifier.local?.type === "Identifier") {
          setDeclaredSemantic(specifier, specifier.local.name, semantic);
        }
      }
    },
    trackVariable(node) {
      trackPattern(node.id, semanticOfExpression(node.init), node);
    },
  };
};
const sourceFileName = (context) =>
  (context.filename ?? context.getFilename?.() ?? "").replaceAll("\\", "/");

const stringValue = (node) =>
  node?.type === "Literal" && String(node.value) === node.value
    ? node.value
    : undefined;

const resolveRelative = (fileName, specifier) => {
  const segments = fileName.split("/").slice(0, -1);
  for (const segment of specifier.split("/")) {
    if (segment === "..") {
      segments.pop();
    } else if (segment !== "." && segment.length > 0) {
      segments.push(segment);
    }
  }
  return segments.join("/");
};

const workspaceSourceRoot = (fileName) => {
  const match = fileName.match(
    /\/(?:apps|packages)\/(?:[^/]+\/)+?src(?:\/|$)/u
  );
  return match?.[0]?.replace(/\/$/u, "");
};

const isPrivatePackageAlias = (specifier) =>
  /^@[^/]+\/[^/]+\/src(?:\/|$)/u.test(specifier);

const isCrossWorkspaceSourcePath = (fileName, specifier) => {
  if (!specifier.startsWith(".")) {
    return false;
  }
  const sourceRoot = workspaceSourceRoot(fileName);
  const target = resolveRelative(fileName, specifier);
  const targetRoot = workspaceSourceRoot(target);
  return (
    sourceRoot !== undefined &&
    targetRoot !== undefined &&
    sourceRoot !== targetRoot
  );
};

const noCrossPackageSourceImports = {
  create(context) {
    const fileName = sourceFileName(context);
    const inspect = (node) => {
      const specifier = stringValue(node.source);
      if (
        specifier !== undefined &&
        (isPrivatePackageAlias(specifier) ||
          isCrossWorkspaceSourcePath(fileName, specifier))
      ) {
        context.report({
          messageId: "noCrossPackageSourceImports",
          node: node.source,
        });
      }
    };
    return {
      ExportAllDeclaration: inspect,
      ExportNamedDeclaration: inspect,
      ImportDeclaration: inspect,
      ImportExpression: inspect,
    };
  },
  meta: {
    docs: {
      description:
        "Prevent imports from another workspace's private source tree.",
    },
    messages: {
      noCrossPackageSourceImports:
        "Import the package's public export instead of reaching into another workspace's source folder.",
    },
    type: "problem",
  },
};

export default {
  meta: { name: "package" },
  rules: {
    "no-cross-package-source-imports": noCrossPackageSourceImports,
  },
};
import { Array as EffectArray } from "effect";

import { createBindingTracker, propertyName } from "./binding-tracker.js";

const bunImportSemantic = (source, specifierType, imported) => {
  if (
    source === "@effect/platform-bun" &&
    specifierType === "ImportSpecifier" &&
    imported === "BunRuntime"
  ) {
    return "BunRuntime";
  }

  if (
    source === "@effect/platform-bun" &&
    specifierType === "ImportNamespaceSpecifier"
  ) {
    return "platform-bun";
  }

  if (source === "@effect/platform-bun/BunRuntime") {
    return specifierType === "ImportSpecifier" && imported
      ? `BunRuntime.${imported}`
      : "BunRuntime";
  }

  return null;
};

const bunHostMethods = new Set([
  "file",
  "serve",
  "spawn",
  "spawnSync",
  "write",
]);

const bunRuntimeSemantics = new Set([
  "BunRuntime.runMain",
  "platform-bun.BunRuntime.runMain",
]);

const destructuresBunHostMethod = (pattern) =>
  pattern?.type === "ObjectPattern" &&
  EffectArray.some(
    pattern.properties,
    (property) =>
      property.type === "Property" &&
      (!property.computed || property.key?.type === "Literal") &&
      bunHostMethods.has(propertyName(property.key))
  );

const isHostMethod = (semantic) =>
  semantic?.startsWith("Global.Bun.") &&
  bunHostMethods.has(semantic.slice("Global.Bun.".length));

const noHostApiOutsideAdapters = {
  create(context) {
    const tracker = createBindingTracker(
      context.sourceCode,
      new Map([["Bun", "Global.Bun"]])
    );

