        ? imported
        : null;
    }
  }

  const moduleSemantics = new Map([
    ["effect/Data", "Data"],
    ["effect/Effect", "Effect"],
    ["effect/ManagedRuntime", "ManagedRuntime"],
    ["effect/Schema", "Schema"],
  ]);
  const moduleSemantic = moduleSemantics.get(source);
  if (!moduleSemantic) {
    return null;
