    return "BunRuntime";
  }

  if (
    source === "@effect/platform-bun" &&
    specifierType === "ImportNamespaceSpecifier"
  ) {
    return "platform-bun";
  }

  if (source === "@effect/platform-bun/BunRuntime") {
    return specifierType === "ImportSpecifier" && imported
